type Result =
  | { status: "loading" }
  | { status: "success"; data: string }
  | { status: "error"; message: string };

function render(r: Result) {
  if (r.status === "success") return r.data;     // narrowed
  if (r.status === "error") return r.message;     // narrowed
  return "Loading…";
}

